class FighterState {
public:
  virtual ~FighterState() {}
  virtual FighterState* handleInput(Fighter& f, Input in) { return nullptr; }
  virtual void update(Fighter& f) {}
};

class CrouchingState : public FighterState {
public:
  virtual FighterState* handleInput(Fighter& f, Input in) {
    if (in == RELEASE_DOWN) return new StandingState();
    return nullptr;  // jump is simply not handled here
  }
  virtual void update(Fighter& f) {
    if (++chargeTime_ == CHARGE_FRAMES) f.fireHadoken();
  }
private:
  int chargeTime_ = 0;  // only meaningful while crouching
};

void Fighter::handleInput(Input in) {
  FighterState* next = state_->handleInput(*this, in);
  if (next) { delete state_; state_ = next; }
}

void Heroine::handleInput(Input input) {
  HeroineState* next = state_->handleInput(*this, input);
  if (next != NULL) {
    state_->exit(*this);
    if (state_->isDynamic()) delete state_;  // static states are shared
    state_ = next;
    state_->enter(*this);
  }
}

class StandingState : public HeroineState {
public:
  virtual void enter(Heroine& h) { h.setGraphics(IMAGE_STAND); }
  virtual HeroineState* handleInput(Heroine& h, Input in) {
    if (in == PRESS_DOWN) return new DuckingState(); // has chargeTime_
    if (in == PRESS_B) return &HeroineState::jumping; // stateless, shared
    return NULL;
  }
};

