class ScreenStack {
public:
  void push(Screen* s) {
    if (!stack_.empty()) stack_.back()->pause();
    stack_.push_back(s);
    s->enter();
  }
  void pop() {
    stack_.back()->exit();
    delete stack_.back();
    stack_.pop_back();
    if (!stack_.empty()) stack_.back()->resume();
  }
  void replace(Screen* s) { pop(); push(s); }
  void handleInput(Input in) { stack_.back()->handleInput(*this, in); }
private:
  std::vector<Screen*> stack_;  // top = current state
};

